def find_path(graph, start, goal):
    open_set = set([start])
    closed_set = set()
    parent = {}
    path = []
    found = False
    while not found and open_set:
        current = min(open_set, key=lambda node: (len(open_set), graph[node]))
        if current == goal:
            found = True
        else:
            open_set.remove(current)
            closed_set.add(current)
            for node in graph[current]:
                if node not in closed_set:
                    open_set.add(node)
                    parent[node] = current
    if found:
        while goal != start:
            path.append(goal)
            goal = parent[goal]
        path.append(start)
        path.reverse()
    return path if found else None
