def find_path(graph, start, goal):
    open_list = [(0, start)]
    visited = set()
    parent = {start: None}
    while open_list:
        cost, current = min(open_list)
        if current == goal:
            path = []
            while current is not None:
                path.append(current)
                current = parent[current]
            return path[::-1]
        visited.add(current)
        for neighbor in graph[current]:
            if neighbor not in visited:
                tentative_cost = cost + 1
                if (neighbor, tentative_cost) not in open_list and (neighbor, tentative_cost) not in visited:
                    open_list.append((tentative_cost, neighbor))
                    parent[neighbor] = current
    return None
