def find_path(graph, start, goal):
    path = []
    visited = set()

    def dfs(node):
        if node == goal:
            path.append(goal)
            return True
        if node in visited:
            return False
        visited.add(node)
        path.append(node)
        for neighbor in graph[node]:
            if dfs(neighbor):
                return True
        return False
    dfs(start)
    return path if path and path[0] == start else None

def find_path(graph, start, goal):
    queue = [(start, [start])]
    visited = set()
    while queue:
        vertex, path = queue.pop(0)
        if vertex in visited:
            continue
        visited.add(vertex)
        if vertex == goal:
            return path
        for neighbor in graph[vertex]:
            if neighbor not in visited:
                queue.append((neighbor, path + [neighbor]))
    return None
